"""Summarize all48 completed deletions without treating them as independent studies."""
from pathlib import Path
import argparse,json
import numpy as np,pandas as pd
p=argparse.ArgumentParser();p.add_argument('--root',required=True);p.add_argument('--out',required=True);a=p.parse_args();r=Path(a.root);out=Path(a.out);out.mkdir(parents=True,exist_ok=True)
jobs=pd.read_csv(r/'inputs/JOB_MANIFEST.tsv',sep='\t');assert len(jobs)==48
TNF='Hallmark::HALLMARK_TNFA_SIGNALING_VIA_NFKB';MAPK='Reactome::REACTOME_MAPK_FAMILY_SIGNALING_CASCADES'
rows=[];fitrows=[];gene_rows=[];repgenes=['Ccl5','Ifih1','Mcl1','Ifit2','Map2k2','Mapk3','Dusp2']
for j in jobs.itertuples():
 d=r/'fits'/j.tissue/j.safe_cell_type/j.omitted_sample_id;assert (d/'gsea/STATUS.txt').read_text().strip()=='COMPLETED_LOO_GSEA'
 inp=r/'inputs'/j.tissue/j.safe_cell_type;b=pd.read_csv(inp/'BASELINE_GSEA.tsv.gz',sep='\t').set_index('pathway_id');g=pd.read_csv(d/'gsea/LOO_GSEA_ALL.tsv.gz',sep='\t').set_index('pathway_id')
 rec=json.loads((d/'FIT_RECORD.json').read_text());gr=pd.read_csv(d/'gsea/GSEA_RECORD.tsv',sep='\t').iloc[0].to_dict();fitrows.append({**rec,**{'gsea_'+k:v for k,v in gr.items()}})
 targets=[TNF]+([MAPK] if j.tissue=='Lateral_wall' and j.safe_cell_type=='Endothelial' else [])
 for target in targets:
  bb=b.loc[target];gg=g.loc[target];ok=gg.test_status=='TESTED' and np.isfinite(gg.NES)
  ble=set(bb.leadingEdge.split(',')) if isinstance(bb.leadingEdge,str) else set();lle=set(gg.leadingEdge.split(',')) if isinstance(gg.leadingEdge,str) else set()
  rows.append({'tissue':j.tissue,'cell_type':j.cell_type,'pathway_id':target,'program':'TNF–NF-kB' if target==TNF else 'MAPK-family signaling','omitted_sample_id':j.omitted_sample_id,'omitted_GSM':j.omitted_GSM,'omitted_condition':j.omitted_condition,'retained_naive':j.retained_naive,'retained_noise':j.retained_noise,'baseline_NES':bb.NES,'baseline_P':bb.P,'baseline_FDR':bb.FDR,'LOO_NES':gg.NES,'LOO_P':gg.P,'LOO_FDR':gg.FDR,'test_status':gg.test_status,'same_direction_as_full':bool(np.sign(bb.NES)==np.sign(gg.NES)) if ok else None,'FDR_below_005':bool(gg.FDR<.05) if ok else None,'NES_change':gg.NES-bb.NES if ok else np.nan,'original_family_size':j.original_family_size,'tested_pathways':int(gr['tested']),'unavailable_pathways':int(gr['unavailable']),'baseline_leading_edge_n':len(ble),'LOO_leading_edge_n':len(lle),'leading_edge_overlap_n':len(ble&lle),'leading_edge_jaccard':len(ble&lle)/len(ble|lle) if ble|lle else np.nan})
 bd=pd.read_csv(inp/'BASELINE_DE.tsv.gz',sep='\t');ld=pd.read_csv(d/'LOO_DE_ALL.tsv.gz',sep='\t').set_index('gene_id')
 bd['absstat']=bd.stat.abs();bd=bd.dropna(subset=['gene_symbol','stat']);bd.gene_symbol=bd.gene_symbol.str.strip();bd=bd.sort_values(['gene_symbol','absstat','stat','gene_id'],ascending=[True,False,False,True],kind='stable').drop_duplicates('gene_symbol').set_index('gene_symbol')
 for gene in repgenes:
  if gene not in bd.index:continue
  bb=bd.loc[gene];gg=ld.loc[bb.gene_id]
  gene_rows.append({'tissue':j.tissue,'cell_type':j.cell_type,'gene_symbol':gene,'gene_id':bb.gene_id,'omitted_sample_id':j.omitted_sample_id,'omitted_GSM':j.omitted_GSM,'omitted_condition':j.omitted_condition,'baseline_log2FoldChange':bb.log2FoldChange,'baseline_lfcSE':bb.lfcSE,'baseline_padj':bb.padj,'LOO_log2FoldChange':gg.log2FoldChange,'LOO_lfcSE':gg.lfcSE,'LOO_padj':gg.padj,'same_gene_id_used_in_full_and_LOO':True})
f=pd.DataFrame(rows);assert len(f)==56;f.to_csv(out/'LOO_FOCUSED_ALL_56.tsv',sep='\t',index=False)
pd.DataFrame(gene_rows).to_csv(out/'LOO_REPRESENTATIVE_GENE_EFFECTS.tsv',sep='\t',index=False)
pd.DataFrame(fitrows).drop(columns=['warnings']).to_csv(out/'ALL_48_FIT_RECORDS.tsv',sep='\t',index=False)
summary=[]
for (t,c,p),z in f.groupby(['tissue','cell_type','pathway_id'],sort=False):
 assert len(z)==8 and z.omitted_sample_id.nunique()==8
 valid=z[z.test_status=='TESTED'].copy();largest=valid.loc[valid.NES_change.abs().idxmax()] if len(valid) else None
 summary.append({'tissue':t,'cell_type':c,'pathway_id':p,'program':z.program.iloc[0],'full_NES':z.baseline_NES.iloc[0],'full_FDR':z.baseline_FDR.iloc[0],'LOO_total':8,'LOO_estimable':len(valid),'same_direction_count':int(valid.same_direction_as_full.sum()),'direction_reversal_count':int((valid.same_direction_as_full==False).sum()),'FDR_below_005_count':int(valid.FDR_below_005.sum()),'LOO_NES_min':valid.LOO_NES.min(),'LOO_NES_max':valid.LOO_NES.max(),'LOO_FDR_min':valid.LOO_FDR.min(),'LOO_FDR_max':valid.LOO_FDR.max(),'largest_NES_change_omitted_sample':largest.omitted_sample_id if largest is not None else None,'largest_NES_change_omitted_GSM':largest.omitted_GSM if largest is not None else None,'largest_absolute_NES_change':valid.NES_change.abs().max(),'leading_edge_jaccard_min':valid.leading_edge_jaccard.min(),'leading_edge_jaccard_max':valid.leading_edge_jaccard.max()})
s=pd.DataFrame(summary);s.to_csv(out/'LOO_STABILITY_SUMMARY.tsv',sep='\t',index=False)
lines=['# Animal-deletion sensitivity analysis','', 'The complete four-versus-four-animal analysis remains the primary result. Forty-eight leave-one-animal-out fits evaluated six tissue–cell-type models, each retaining three animals from one condition and four from the other. The seven displayed pathway/model combinations cover TNF–NF-kB in all six models and MAPK-family signaling in lateral-wall endothelial cells. All individual animal identities, directions, NES and FDR values are supplied in `LOO_FOCUSED_ALL_56.tsv`.','', '| Tissue | Cell type | Pathway | Full NES | Full FDR | Same direction | LOO FDR < 0.05 | LOO NES range | LOO FDR range |','|---|---|---|---:|---:|---:|---:|---:|---:|']
for x in s.itertuples():lines.append(f'| {x.tissue} | {x.cell_type} | {x.program} | {x.full_NES:.3f} | {x.full_FDR:.3g} | {x.same_direction_count}/{x.LOO_estimable} | {x.FDR_below_005_count}/{x.LOO_estimable} | {x.LOO_NES_min:.3f} to {x.LOO_NES_max:.3f} | {x.LOO_FDR_min:.3g} to {x.LOO_FDR_max:.3g} |')
lines+=['','## Interpretation','', 'The eight deletion estimates for each model overlap in seven of eight source animals and must not be treated as eight independent replications. Direction stability and changes in adjusted P values are reported separately. Removing one animal changes information, normalization and dispersion estimates; crossing FDR 0.05 alone is not a direction reversal. No post hoc animal exclusion or replacement of the main analysis was made. These separate cell-type fits do not test a condition-by-cell-type interaction.','', 'The original full-model fitted gene mask was retained. Normalization and dispersion were re-estimated for each seven-animal dataset using the original PyDESeq2 design and settings. Enrichment retained the frozen original Hallmark-plus-Reactome memberships and the original eligible testing family for each model. BH family sizes stayed fixed, including unavailable members where applicable. The LOO FDR values are family-specific sensitivity summaries; there was no pooled confirmatory FDR across deletion iterations.','', 'Per-animal expression summaries use the original full-fit normalized pseudobulk counts. Representative-gene values and all displayed pathway-member counts are available with sample identities. The pathway expression profile is the unsigned equal-weight mean of gene-standardized log1p normalized counts, using sample SD across the original eight animals. It is a descriptive score, not NES, a cell-level test or a power calculation.','', 'The finite sample size and broad cell annotations remain limitations. This exercise evaluates influence of observed animals under the existing annotation and modeling choices; it does not establish biological replication in the separate pooled-library localization dataset.']
(out/'SENSITIVITY_REPORT.md').write_text('\n'.join(lines)+'\n')
(out/'COMPLETION_SUMMARY.json').write_text(json.dumps({'status':'COMPLETE','LOO_models':48,'focused_records':56,'representative_gene_records':len(gene_rows),'pathway_model_summaries':summary,'main_analysis_modified':False,'new_dependencies_installed':False},indent=2,default=lambda x:x.item() if hasattr(x,'item') else str(x)))
print(s.to_string(index=False))
